#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<vector<bool>> hasEdge;
    if(n <= 5000){
        hasEdge.assign(n+1, vector<bool>(n+1, false));
    }

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        if(n <= 5000) hasEdge[u][v] = true;
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count();};

    auto he = [&](int u, int v) -> bool {
        if(n <= 5000) return hasEdge[u][v];
        for(int w : adj[u]) if(w == v) return true;
        return false;
    };

    // DAG check
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo; topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]){
                    if(dp[v] + 1 > dp[u]){
                        dp[u] = dp[v] + 1;
                        nxt[u] = v;
                    }
                }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){
                if(i) cout << ' ';
                cout << path[i];
            }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    // DFS for small graphs
    if(n <= 25){
        vector<bool> vis(n+1, false);
        vector<int> cur_path;
        bool found = false;
        function<void(int)> dfs = [&](int u){
            if(found || elapsed_ms() > 3800) return;
            cur_path.push_back(u); vis[u] = true;
            if((int)cur_path.size() > (int)best_path.size()) best_path = cur_path;
            if((int)cur_path.size() == n){ found = true; vis[u]=false; cur_path.pop_back(); return; }
            vector<pair<int,int>> nb;
            for(int v : adj[u]) if(!vis[v]){
                int c=0; for(int w : adj[v]) if(!vis[w]) c++;
                nb.push_back({c,v});
            }
            sort(nb.begin(), nb.end());
            for(auto&[c,v]:nb){
                if(found || elapsed_ms()>3800) break;
                dfs(v);
            }
            vis[u]=false; cur_path.pop_back();
        };
        vector<int> order(n); iota(order.begin(),order.end(),1);
        shuffle(order.begin(),order.end(),rng);
        for(int s:order){ if(found||elapsed_ms()>3800) break; dfs(s); }
        if(found || (int)best_path.size() == n){
            cout << best_path.size() << "\n";
            for(int i=0;i<(int)best_path.size();i++){ if(i) cout<<' '; cout<<best_path[i]; }
            cout<<"\n"; return 0;
        }
    }

    // Greedy with restarts + insertion improvement
    while(elapsed_ms() < 3700 && (int)best_path.size() < n){
        int sv = rng() % n + 1;
        vector<int> path;
        vector<bool> used(n+1, false);
        path.push_back(sv); used[sv] = true;

        // Extend back with Warnsdorff + randomness
        auto ext_back = [&]() -> bool {
            int c = path.back();
            int best=-1, bs=INT_MAX;
            for(int v : adj[c]) if(!used[v]){
                int s=0; for(int w : adj[v]) if(!used[w]) s++;
                if(s < bs || (s == bs && (rng()&1))){ bs=s; best=v; }
            }
            if(best==-1) return false;
            used[best]=true; path.push_back(best); return true;
        };
        auto ext_front = [&]() -> bool {
            int c = path[0];
            int best=-1, bs=INT_MAX;
            for(int v : radj[c]) if(!used[v]){
                int s=0; for(int w : radj[v]) if(!used[w]) s++;
                if(s < bs || (s == bs && (rng()&1))){ bs=s; best=v; }
            }
            if(best==-1) return false;
            used[best]=true; path.insert(path.begin(), best); return true;
        };

        for(int r=0;r<4;r++){ while(ext_back()); while(ext_front()); }

        // Vertex insertion
        if(n <= 5000){
            for(int v=1;v<=n;v++){
                if(used[v]) continue;
                if(he(v, path[0])){ path.insert(path.begin(),v); used[v]=true; continue; }
                if(he(path.back(), v)){ path.push_back(v); used[v]=true; continue; }
                for(int i=0;i+1<(int)path.size();i++){
                    if(he(path[i],v) && he(v,path[i+1])){
                        path.insert(path.begin()+i+1, v); used[v]=true; break;
                    }
                }
            }
        }

        if((int)path.size() > (int)best_path.size()) best_path = path;
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){ if(i) cout<<' '; cout<<best_path[i]; }
    cout << "\n";
    return 0;
}
